import re
import numpy as np

# all-MiniLM-L6-v2 needs PyTorch and a model download, which this sandbox cannot do.
# encode() is a tiny offline stand-in: like the real model it turns text into a
# unit-length vector, and texts about the same topic point in the same direction.
TOPIC_WORDS = {
    0: {"plant", "plants", "sunlight", "light", "photosynthesis", "energy", "leaves"},
    1: {"recipe", "flour", "egg", "baking", "bake", "ingredients", "cups", "cake"},
    2: {"revenue", "percent", "company", "financial", "growth", "grew", "quarterly", "profit"},
}


def encode(text):
    """Return a unit-length 4-dimensional embedding (dimension 3 collects all other words)."""
    vec = np.full(4, 0.01)
    for word in re.findall(r"[a-z]+", text.lower()):
        for dim, words in TOPIC_WORDS.items():
            if word in words:
                vec[dim] += 1.0
                break
        else:
            vec[3] += 0.1
    return vec / np.linalg.norm(vec)


def cosine_similarity(a, b):
    """Cosine of the angle between vectors a and b (1.0 = same direction, 0.0 = unrelated)."""
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b)))


def best_match(query, documents):
    """Return the document most semantically similar to the query."""
    q = encode(query)
    scores = [cosine_similarity(q, encode(doc)) for doc in documents]
    return documents[int(np.argmax(scores))]


docs = [
    "Photosynthesis lets plants make food from sunlight.",
    "The recipe needs two cups of flour and an egg.",
    "Quarterly revenue grew by twelve percent.",
]
print(best_match("how plants turn light into energy", docs))
